package com.riedel.beyondborders.data.visa

/**
 * What one place asks of the bundled passport.
 *
 * Reference data like [com.riedel.beyondborders.data.place.Place], generated by
 * tools/visa/build_visa.py. Every place in the registry has exactly one of these —
 * the build script refuses to write the asset otherwise, because a destination
 * that silently has no answer is worse than a build that fails.
 */
data class VisaRequirement(
    /** Matches [com.riedel.beyondborders.data.place.Place.code]. */
    val code: String,
    val category: VisaCategory,
    /** Visa-free days, where the dataset or the curator states a number. */
    val days: Int?,
    val origin: VisaOrigin,
    /** Present for curated entries only: written for a traveller, shown verbatim. */
    val note: String?,
    /** Present for curated entries only. */
    val confidence: VisaConfidence?,
    /** Present for curated entries only: what the note rests on. */
    val sourceUrl: String?,
    /**
     * For a [VisaOrigin.CORRECTION], the raw cell we are overruling. Shown so a
     * disagreement with upstream is visible rather than hidden.
     */
    val datasetSaid: String?,
    /**
     * The Auswärtiges Amt travel-advice page — the authority this app defers to.
     * Null only for Germany and Antarctica, neither of which has one.
     */
    val officialUrl: String?,
    /**
     * Set when [officialUrl] is the *parent's* page rather than this place's, and
     * holds the parent's code. Greenland's link goes to the Denmark page, so the
     * UI says so instead of implying the page is about Greenland.
     */
    val officialFor: String?,
) {
    /** True where nothing has to be arranged before boarding. */
    val isVisaFree: Boolean
        get() = category == VisaCategory.VISA_FREE || category == VisaCategory.HOME

    /** True where no embassy appointment stands between you and the trip. */
    val isEasy: Boolean
        get() = isVisaFree ||
            category == VisaCategory.ETA ||
            category == VisaCategory.VISA_ON_ARRIVAL
}

/**
 * The requirement categories, in ramp order.
 *
 * The order is load-bearing — it drives the map's colour ramp and the list's
 * sort — and it is monotonic in one specific thing: how much can go wrong between
 * deciding to go and standing at the border.
 *
 * [VISA_ON_ARRIVAL] sits after [ETA] despite needing no advance paperwork,
 * because an ETA is a near-instant online yes/no while a visa on arrival is a
 * queue, a fee in cash and an official's discretion.
 *
 * [CHECK] is the dataset's `special` status: the rule is real but does not fit any
 * other category (a tourist card, an invitation, a travel ban), so the row's own note
 * is the answer. It sorts after [VISA_REQUIRED] and before the permit regimes. With
 * two passports the lower ordinal wins, so a definite visa path on the other passport
 * beats it, while it beats a definite permit or refusal: it is not assumed to be as
 * closed as those.
 *
 * [PERMIT_REQUIRED] is ours rather than the dataset's. The seven uninhabited
 * places need permission from a research programme or a nature-reserve
 * authority; filing that under [VISA_REQUIRED] would send someone looking for an
 * embassy counter that does not exist.
 *
 * The names match the asset's strings exactly, so [parse] can be a `valueOf`.
 */
enum class VisaCategory(val label: String) {
    HOME("Home"),
    VISA_FREE("Visa-free"),
    ETA("Travel authorisation"),
    VISA_ON_ARRIVAL("Visa on arrival"),
    E_VISA("e-Visa"),
    VISA_REQUIRED("Visa required"),
    CHECK("Check requirements"),
    PERMIT_REQUIRED("Permit required"),
    NO_ADMISSION("No entry"),
    ;

    companion object {
        /**
         * Null rather than a throw for an unknown name, so that an asset written
         * by a newer build degrades to "no answer for this place" instead of
         * taking the whole screen down. The build script is what guarantees the
         * vocabulary; this is the seatbelt.
         */
        fun parseOrNull(raw: String): VisaCategory? = entries.firstOrNull { it.name == raw }
    }
}

/** Where a requirement came from, which the app shows rather than hides. */
enum class VisaOrigin {
    /** Straight out of the dataset row. */
    DATASET,

    /** Hand-written in tools/visa/rules.py, because the dataset has no row. */
    CURATED,

    /** Hand-written, and overruling a row the dataset does have. */
    CORRECTION,
    ;

    companion object {
        fun parseOrNull(raw: String): VisaOrigin? = when (raw) {
            "dataset" -> DATASET
            "curated" -> CURATED
            "correction" -> CORRECTION
            else -> null
        }
    }
}

/**
 * How much a curated entry is worth.
 *
 * Shown in the UI on purpose. 53 of the 252 places are hand-researched and some
 * of that research is thinner than the rest — American Samoa's refusal of ESTA is
 * certain, its 30-day grant is not. Presenting all 53 in the same authoritative
 * voice would be the dishonest option.
 */
enum class VisaConfidence(val label: String) {
    HIGH("Well established"),
    MEDIUM("Likely right, details may vary"),
    LOW("Uncertain — check before booking"),
    ;

    companion object {
        fun parseOrNull(raw: String): VisaConfidence? =
            entries.firstOrNull { it.name.equals(raw, ignoreCase = true) }
    }
}
